package agentusageview

import (
	"time"

	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/agentusage"
)

// listSessionsCmd resolves the projects root and lists it, all inside the Cmd:
// the model is not touched (Rule 110) and the answer carries gen back.
func listSessionsCmd(gen int) tea.Cmd {
	return func() tea.Msg {
		root, err := agentusage.ProjectsRoot()
		if err != nil {
			return sessionListLoadedMsg{gen: gen, err: err}
		}
		listing, err := agentusage.ListSessions(root)
		return sessionListLoadedMsg{gen: gen, root: root, listing: listing, err: err}
	}
}

// parseSessionCmd locates and parses a session's transcripts, all inside the
// Cmd (Rule 110). parent is copied in by the caller; the answer carries gen.
func parseSessionCmd(gen int, parent string) tea.Cmd {
	return func() tea.Msg {
		files, err := agentusage.LocateSession(parent)
		if err != nil {
			return sessionUsageLoadedMsg{gen: gen, err: err}
		}
		usage, err := agentusage.ParseSession(files)
		return sessionUsageLoadedMsg{gen: gen, usage: usage, err: err}
	}
}

// pollInterval is the pause between two reads of the open session; a variable
// so tests can shorten it. quietPeriod is how long a session must be quiet to
// be considered settled and no longer polled.
var (
	pollInterval = 2 * time.Second
	quietPeriod  = 5 * time.Minute
)

// now is the clock the poll chain reads, replaceable in tests.
var now = time.Now

// usageDeltaMsg carries one incremental read. gen is agentGen at the time the
// read started; at is when it finished.
type usageDeltaMsg struct {
	gen   int
	delta agentusage.Delta
	err   error
	at    time.Time
}

// usagePollTickMsg says the poll interval of generation gen has elapsed.
type usagePollTickMsg struct{ gen int }

// agentsResumeMsg asks Update to restart a poll chain that stopped.
type agentsResumeMsg struct{}

// readDeltaCmd reads what changed since c. It owns its Cursor copy and touches
// no model (Rule 110); the answer carries gen and the time of the read.
func readDeltaCmd(gen int, c agentusage.Cursor) tea.Cmd {
	return func() tea.Msg {
		delta, err := agentusage.ReadDelta(c)
		return usageDeltaMsg{gen: gen, delta: delta, err: err, at: now()}
	}
}

// pollTickCmd waits pollInterval, then answers with a tick of generation gen.
func pollTickCmd(gen int) tea.Cmd {
	return tea.Tick(pollInterval, func(time.Time) tea.Msg { return usagePollTickMsg{gen: gen} })
}

// resumeCmd answers agentsResumeMsg at once.
func resumeCmd() tea.Cmd {
	return func() tea.Msg { return agentsResumeMsg{} }
}
package agentusageview

import (
	"fmt"
	"slices"
	"strings"

	"github.com/anthnel/devdesk/internal/agentusage"
)

// mainKey is the key of the orchestrator, of which a session has one.
const mainKey = "main"

// agentKeys names agents so the same one keeps its key from one rebuild to the
// next: "main" for the orchestrator, "sub:<ID>#n" for a sub-agent, n counting
// the earlier agents that share its ID (an ID is not guaranteed unique). It
// must be given the canonical order (agentRows), never the sorted or filtered
// one: under a sort, two twins would trade keys whenever they trade ranks.
func agentKeys(agents []agentusage.Agent) []string {
	seen := make(map[string]int, len(agents))
	keys := make([]string, len(agents))
	for i, a := range agents {
		if a.Main {
			keys[i] = mainKey
			continue
		}
		keys[i] = fmt.Sprintf("sub:%s#%d", a.ID, seen[a.ID])
		seen[a.ID]++
	}
	return keys
}

// populationOf lists what makes a table "another population" for the column
// widths: which agents it holds, and the models each one names. Counts change
// on every delta and do not count. A type can change too (its meta arrives
// after the transcript) but stays out on purpose: the column is remeasured at
// the next ctrl+r or change of population.
func populationOf(rows []agentRow) []string {
	out := make([]string, len(rows))
	for i, r := range rows {
		out[i] = r.key + "|" + strings.Join(r.Models, ",")
	}
	return out
}

// withUsage shows u in the agents table, keeping the cursor on the agent it was
// on (whatever the filter and the sort do to the order), and clears the
// loading and error states. The columns are remeasured only on a full read or
// when the population changed, so a two-second delta never reshuffles them.
func (m Model) withUsage(u agentusage.Usage, full bool) Model {
	before := populationOf(m.agentTable.Items())
	selected, hadSelection := m.selectedAgentKey()
	cursor := m.agentTable.Cursor()

	rows := agentRows(u, m.agentsTree())
	m.usage = u
	m.agentsLoading, m.agentsErr = false, false
	m.agentTable.SetItems(rows)

	if full || !slices.Equal(before, populationOf(rows)) {
		m.agentTable.Remeasure()
	}
	m.agentTable.SetCursor(cursor) // clamps when the agent vanished
	if hadSelection {
		m.selectAgentKey(selected)
	}
	return m
}

// selectAgentKey moves the cursor onto the visible row with that key, if any.
func (m *Model) selectAgentKey(key string) {
	if i := slices.IndexFunc(m.agentTable.Visible(), func(r agentRow) bool { return r.key == key }); i >= 0 {
		m.agentTable.SetCursor(i)
	}
}

// selectedAgentKey is the key of the row under the cursor.
func (m Model) selectedAgentKey() (string, bool) {
	r, ok := m.agentTable.Selected()
	return r.key, ok
}

