			t.Fatal("a Cmd of the batch did not answer")
		}
	}
	return msgs
}

func usageMsgs(msgs []tea.Msg) []sessionUsageLoadedMsg {
	var got []sessionUsageLoadedMsg
	for _, m := range msgs {
		if u, ok := m.(sessionUsageLoadedMsg); ok {
			got = append(got, u)
		}
	}
	return got
}

